(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-medicine-and-surgery-i-exam-6"]={"title":"Clinical Medicine and Surgery I Exam 6","sections":[{"id":"l33-emph","title":"★ Professor Emphasized — Who Gets Oxygen, Who Qualifies, Fire","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l33-devices","title":"Delivery Devices","style":"--acc:#7a2d30;--acc-bg:#ece2e2;--acc-zebra:#f6f0f1;--acc-ink:#5f2325"},{"id":"l33-neb","title":"Nebulizers, Response & Education","style":"--acc:#b45357;--acc-bg:#f4e7e7;--acc-zebra:#faf3f3;--acc-ink:#8c4144"},{"id":"l34-emph","title":"★ Professor Emphasized — Normals, Winter Formula, Anion Gap","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l34-read","title":"Reading the Gas & Compensation","style":"--acc:#7a2d30;--acc-bg:#ece2e2;--acc-zebra:#f6f0f1;--acc-ink:#5f2325"},{"id":"l34-resp","title":"Respiratory Acidosis & Alkalosis","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l34-metab","title":"Metabolic Alkalosis & Acidosis","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l34-lytes","title":"Electrolytes & Oxygen","style":"--acc:#1f5c3a;--acc-bg:#e0e8e3;--acc-zebra:#eff4f1;--acc-ink:#18482d"}],"rows":[{"t":"★ Indications","d":"<b>Hypoxia</b>; acute medical or surgical needs (perioperative, postoperative); respiratory conditions (<b>carbon monoxide poisoning</b>); special indications without hypoxia: <b>air hunger</b> (end of life) and <b>cluster headache</b>. &ldquo;One of the big things.&rdquo;","s":0},{"t":"★ Fire","d":"Benefit: correction of hypoxia, symptom relief, therapeutic benefit. Risk: <b>fire hazard</b> &mdash; &ldquo;probably one of the biggest risks.&rdquo; Also hypercapnia (carbon dioxide retention), mucosal irritation, vasoconstriction.","s":0},{"t":"Myocardial infarction","d":"Vasoconstriction: <b>not given unless saturation is below 91%</b> (the slide&rsquo;s value; current guidelines use 90%).","s":0},{"t":"★ Home qualification","d":"Documented hypoxia by arterial blood gas or pulse oximetry at rest, with exertion and/or during sleep, <b>performed at the time of need</b>. Rest: saturation <b>&le; 88%</b> on room air or partial pressure of oxygen <b>&le; 55 mm Hg</b>. Exertion: <b>&le; 88% and improves with oxygen</b>. Sleep: <b>&le; 88% with a drop of 5% or more</b>.","s":0},{"t":"Group I vs II","d":"<b>Group I</b> (qualifies): &le; 55 mm Hg or &le; 88% &rarr; recertify at <b>12 months</b>. <b>Group II</b> (conditional): 56&ndash;59 mm Hg or 89% <b>plus</b> pulmonary hypertension, cor pulmonale (right heart failure) or polycythemia (hematocrit above 56%) &rarr; recertify at <b>3 months</b>.","s":0},{"t":"Varies or fixed","d":"Nasal cannula, simple mask: fraction varies with respiratory rate, inspiratory flow, tidal volume. Partial rebreather, non-rebreather: varies with patient demand. <b>Air entrainment (Venturi, air-entrainment nebulizer): fixed</b>, does not fluctuate.","s":1},{"t":"Nasal cannula","d":"<b>Low flow</b>, 1&ndash;6 L/min, <b>24&ndash;44%</b> (room air 21%; about <b>+4% per liter</b>: 1 = 24, 2 = 28, 3 = 32, 4 = 36, 5 = 40, 6 = 44). Maxes at 44% even above 6 L/min. <b>Humidity above 4 L/min.</b> Mild hypoxia; most commonly used.","s":1},{"t":"Simple mask","d":"<b>Low flow</b>, 5&ndash;10 L/min, .35&ndash;.50 (5&ndash;6 L/min 35%, 6&ndash;7 40%, 7&ndash;8 50%). Mild to moderate respiratory distress.","s":1},{"t":"Partial rebreather","d":"Some exhaled gas gets into the reservoir bag; <b>not commonly used</b>. Its fraction differs between slides (60&ndash;80% vs .40&ndash;.70): never tested.","s":1},{"t":"Non-rebreather","d":"<b>Low flow device, but with a high fraction</b>: 10&ndash;15 L/min = <b>60&ndash;100%</b>. Reservoir bag + one-way valve (no inhaling exhaled air). Flow set to <b>keep the bag from collapsing</b>. <b>Severely hypoxic patients still ventilating well.</b>","s":1},{"t":"Venturi mask","d":"<b>High flow</b>, precise; ports change the fraction; 4&ndash;10 L/min &rarr; <b>24&ndash;50%</b>; total flow above inspiratory demand. <b>Chronic obstructive pulmonary disease</b> (precision).","s":1},{"t":"Air-entrainment nebulizer","d":"Aerosol mask, open face mask, T-piece, tracheostomy collar. Can deliver higher but <b>not recommended above .50</b>.","s":1},{"t":"Advanced airways","d":"Bag-valve mask (resuscitator bag); oropharyngeal and nasopharyngeal airways; endotracheal tube, tracheostomy; tube changer and bougie; laryngeal mask airway.","s":1},{"t":"Why a nebulizer","d":"Liquid medication <b>directly to the airways</b>; medication chosen for the specific treatment; <b>secretion clearance</b>; <b>inhalers are challenging</b> in certain situations; <b>severe exacerbations</b> of respiratory illness.","s":2},{"t":"Is it working?","d":"Clinical: symptoms, work of breathing, color and perfusion. Objective: saturation improves (target varies); blood gas shows a <b>higher oxygen without a higher carbon dioxide</b> and a corrected pH. Vital signs; watch for complications.","s":2},{"t":"★ Home safety","d":"Highly flammable, compressed gas. <b>No smoking</b>; &ldquo;No Smoking&rdquo; and &ldquo;Oxygen in Use&rdquo; signs. <b>At least 10 feet</b> from heat sources (pilot lights, electric appliances, candles). <b>No petroleum products</b> (lip balms, lotions, oils, grease). Smoke and carbon monoxide alarms <b>tested monthly</b>. Proper storage and disposal.","s":2},{"t":"★ Normal values","d":"pH <b>7.35&ndash;7.45</b> (&ldquo;burn this into your eyeballs&rdquo;); carbon dioxide <b>36&ndash;44</b> mm Hg (midpoint 40); bicarbonate <b>22&ndash;26</b> mEq/L (midpoint 24). Acidemia below 7.35, alkalemia above 7.45.","s":3},{"t":"★ Winter formula","d":"Metabolic acidosis: expected carbon dioxide = <b>1.5 &times; bicarbonate + 8, &plusmn; 2</b>. Higher than expected = <b>added respiratory acidosis</b>, can signal impending respiratory failure.","s":3},{"t":"★ Anion gap","d":"<b>Sodium &minus; (chloride + bicarbonate)</b>, normal <b>9&ndash;15</b>. Above 15 = elevated-gap acidosis.","s":3},{"t":"★ Treatment","d":"&ldquo;Always going to be correct the underlying disorder.&rdquo; Therapy aimed at the pH itself only when it is unsustainable: <b>below 6.7 or above 7.6</b>.","s":3},{"t":"★ Frequent questions","d":"Obesity hypoventilation triad; paper bag = placebo; saline responsive is the common alkalosis; carbon dioxide rarely above 55 in compensation; urine chloride splits the alkaloses.","s":3},{"t":"Steps","d":"1. pH: acidosis or alkalosis. 2. Which value (carbon dioxide or bicarbonate) matches the pH. 3. Mixed? pH more or less than expected. 4. Compensation: respiratory disorder &rarr; expected <b>bicarbonate</b>; metabolic disorder &rarr; expected <b>carbon dioxide</b>. 5. Don&rsquo;t neglect the patient.","s":4},{"t":"Rules","d":"Compensation <b>never returns pH to normal</b> and never past it; respiratory cause &rarr; renal compensation; metabolic cause &rarr; respiratory compensation. Normal pH with abnormal values = <b>mixed disorder</b>.","s":4},{"t":"Ratios (given in questions)","d":"Respiratory acidosis: bicarbonate +<b>1</b> per 10 mm Hg acute, +<b>3.5</b> chronic. Respiratory alkalosis: &minus;<b>2</b> per 10 acute, &minus;<b>5</b> chronic. Metabolic acidosis: carbon dioxide &minus;1.3 per 1 mEq/L (use Winter). Metabolic alkalosis: +<b>0.75</b> per 1 mEq/L, <b>rarely above 55</b> (above = concurrent respiratory acidosis).","s":4},{"t":"Timing","d":"Renal compensation <b>begins 6&ndash;12 hours</b> after onset, complete over <b>days</b>: small bicarbonate change = acute, large = chronic.","s":4},{"t":"Algorithm","d":"pH below 7.4 + carbon dioxide above 40 = respiratory acidosis (acute or chronic?); below 40 = compensating metabolic acidosis (check the gap). pH above 7.4 + carbon dioxide above 40 = compensating metabolic alkalosis; below 40 = respiratory alkalosis.","s":4},{"t":"Respiratory acidosis","d":"Hypoventilation &rarr; carbon dioxide above 40 &rarr; low pH, &plusmn; hypoxemia. Somnolence, confusion, altered mental status, asterixis, myoclonus; severe: raised cerebral blood flow and intracranial pressure, papilledema. Labs: low pH, high carbon dioxide, high bicarbonate, <b>hypochloremia if chronic</b> (ammonium chloride excretion).","s":5},{"t":"Acute causes","d":"Airway obstruction; pneumonia, asthma, pulmonary edema, aspiration pneumonitis; central nervous system depression (recreational drugs, intracranial catastrophe, intravenous sedation); myasthenia gravis, Guillain-Barr&eacute; syndrome; pneumothorax, flail chest.","s":5},{"t":"Chronic causes","d":"<b>Chronic obstructive pulmonary disease</b> (&ldquo;first thing that comes to mind&rdquo;), interstitial lung disease, idiopathic pulmonary fibrosis; muscular dystrophy, amyotrophic lateral sclerosis; <b>★ obesity hypoventilation (Pickwickian) syndrome: obesity + sleep disordered breathing + chronic hypercapnia</b>.","s":5},{"t":"Treat","d":"Underlying cause. Acute: <b>restore ventilation</b>. Chronic: <b>careful oxygen titration</b>; avoid rapid carbon dioxide reduction &rarr; <b>post-hypercapnic metabolic alkalosis</b>.","s":5},{"t":"Respiratory alkalosis","d":"Hyperventilation &rarr; low carbon dioxide &rarr; high pH. Light-headedness, anxiety, perioral numbness, paresthesias; severe: <b>tetany</b> (high pH binds calcium to albumin). Compensation: cells trade hydrogen ions for potassium, then kidneys excrete bicarbonate and keep chloride (low bicarbonate, hypokalemia, hyperchloremia).","s":5},{"t":"Alkalosis causes","d":"Psychogenic, stroke, raised intracranial pressure; hypoxia (high altitude, severe anemia, ventilation-perfusion mismatch, hypotension); salicylates, caffeine, nicotine, catecholamines, thyroxine; pulmonary embolism, pneumonia, pulmonary edema, mechanical hyperventilation, interstitial lung disease; pregnancy, hyperthyroidism; septicemia, heat exposure, hepatic failure.","s":5},{"t":"Treat","d":"Underlying cause; usually self-limited. <b>★ Paper bag not necessary</b>: does not correct carbon dioxide, may lower oxygen, placebo. Rapid correction of chronic alkalosis &rarr; post-hypocapnia metabolic acidosis.","s":5},{"t":"Metabolic alkalosis","d":"High bicarbonate &rarr; high pH. No characteristic findings; orthostatic hypotension; hypokalemia &rarr; weakness, hyporeflexia. Labs: high pH and bicarbonate, raised carbon dioxide, low potassium, low chloride.","s":6},{"t":"★ Urine chloride","d":"<b>Below 25 mEq/L = saline responsive</b> (more common; volume contraction): diuretics, post-hypercapnia, vomiting or nasogastric suction, antacids, volume contraction. <b>Above 40 = saline unresponsive</b> (euvolemic or hypervolemic) &rarr; check <b>blood pressure</b>.","s":6},{"t":"Unresponsive groups","d":"<b>Normotensive:</b> severe potassium depletion; hypoparathyroidism and hypercalcemia. <b>Hypertensive:</b> primary aldosteronism, exogenous alkali, mineralocorticoids, <b>licorice</b> (&ldquo;a unicorn&rdquo;).","s":6},{"t":"Treat alkalosis","d":"Underlying cause; saline responsive: <b>isotonic saline</b> and <b>stop diuretics</b>.","s":6},{"t":"Metabolic acidosis","d":"Low bicarbonate &rarr; low pH, low carbon dioxide; hyperkalemia may be present. Signs of the cause + compensatory hyperventilation; <b>Kussmaul respirations</b> (increased tidal volume and tachypnea) in diabetic ketoacidosis. Normal gap = hyperchloremic; elevated gap = normochloremic.","s":6},{"t":"Elevated gap: MUDPILES","d":"Methanol, metformin &middot; uremia &middot; diabetic ketoacidosis &middot; paraldehyde &middot; isoniazid, iron &middot; lactic acidosis &middot; ethylene glycol &middot; salicylates, starvation.","s":6},{"t":"Normal gap: USEDCAR","d":"Ureteral diversion &middot; saline infusion &middot; exogenous acid &middot; diarrhea &middot; carbonic anhydrase inhibitors &middot; adrenal insufficiency &middot; renal tubular acidosis (bicarbonate loss, chloride retention).","s":6},{"t":"Gap pitfalls","d":"Albumin makes most of the normal gap; <b>hypoalbuminemia</b>, sodium extremes and antibiotics distort it. A normal gap does not exclude acidosis and should not override clinical concern. Fewer unmeasured cations (calcium, magnesium, potassium) raise it.","s":6},{"t":"Potassium","d":"<b>Acidosis</b>: hydrogen into cells, potassium out &rarr; <b>hyperkalemia</b>. <b>Alkalosis</b>: potassium into cells &rarr; <b>hypokalemia</b>.","s":7},{"t":"Oxygen","d":"<b>Acidosis</b>: lower hemoglobin affinity, curve <b>right</b>, <b>more</b> oxygen to tissues. <b>Alkalosis</b>: higher affinity, curve <b>left</b>, <b>less</b> oxygen to tissues.","s":7},{"t":"Unsustainable pH","d":"<b>Below 6.7 or above 7.6</b>: cardiac hypocontractility and irritability, seizures, cerebral edema, metabolic disturbances.","s":7},{"t":"Buffers","d":"Chemical buffering (extracellular, intracellular), respiratory (carbon dioxide, fast), renal (bicarbonate, hours to days). Water + carbon dioxide &harr; carbonic acid &harr; hydrogen ion + bicarbonate. Brainstem chemoreceptor: more carbon dioxide &rarr; lower cerebral pH &rarr; more breathing. Hypercapnia usually from <b>under-excretion</b>.","s":7}],"map":{"clinical-medicine-and-surgery-i-exam-6-acid-base-part-1-quiz-version-2":[44,18,33,22,29,43,26,16,24,42,22,43,44,18,44,36,34,18,23,31,17,17,42,18,-1,34,32,41,-1,31],"clinical-medicine-and-surgery-i-exam-6-acid-base-part-1-quiz":[35,32,17,18,41,16,29,26,25,33,30,-1,44,28,18,21,42,31,26,36,26,18,31,22,44,44,30,17,16,37],"clinical-medicine-and-surgery-i-exam-6-acid-base-part-1-vignettes-version-2":[32,16,21,30,23,41,33,33,-1,30,17,-1,28,18,26,33,-1,43,34,24,28,39,17,-1,39,-1,43,34,23,16],"clinical-medicine-and-surgery-i-exam-6-acid-base-part-1-vignettes":[37,18,17,16,17,39,-1,23,44,34,42,18,-1,34,29,42,36,-1,-1,37,30,44,17,17,23,26,18,37,37,18],"clinical-medicine-and-surgery-i-exam-6-oxygen-delivery-quiz-version-2":[14,13,11,8,0,15,6,12,3,7,3,2,15,13,8,13,1,1,7,6,6,15,42,13,3,42,7,3,11,3],"clinical-medicine-and-surgery-i-exam-6-oxygen-delivery-quiz":[11,1,3,4,9,2,10,10,42,10,13,10,12,42,15,6,15,5,12,15,3,4,6,4,0,0,14,9,0,6],"clinical-medicine-and-surgery-i-exam-6-oxygen-delivery-vignettes-version-2":[3,13,5,3,19,4,7,9,7,-1,4,10,15,6,9,42,2,11,42,6,4,6,4,15,11,15,15,3,7,7],"clinical-medicine-and-surgery-i-exam-6-oxygen-delivery-vignettes":[2,9,15,10,14,3,0,3,9,15,11,15,4,9,14,2,15,2,13,0,3,4,42,10,6,4,6,15,4,13]}};
